# Update build info and project name with branch/commit from git
branch_name = os.environ.get('BITBUCKET_BRANCH', '')
short_hash = ''
try:
    from git import Repo
    repo = Repo(os.path.abspath('../..'))  # Go up two levels from docs/src/ to repo root
    head_commit = repo.head.commit
    short_hash = str(head_commit)[:8]

    if not branch_name:
        try:
            branch_name = repo.active_branch.name
        except TypeError:
            branch_name = ''

    build_info['author_name'] = head_commit.author.name
    build_info['author_email'] = head_commit.author.email
    build_info['author_date'] = head_commit.authored_datetime.isoformat() # Datetime object for author date

    # You can also get committer information
    build_info['committer_name'] = head_commit.committer.name
    build_info['committer_email'] = head_commit.committer.email
    build_info['commit_date'] = head_commit.committed_datetime.isoformat() # Datetime object for commit date

except Exception as e:
    print(f"{e!r}. Not populating build info except version")

if branch_name and short_hash:
    project = f'chFPGA ({branch_name} @ {short_hash})'
elif branch_name:
    project = f'chFPGA ({branch_name})'
else:
    project = 'chFPGA ' + version

